# Regex for a valid SemVer 2.0.0 string (no leading zeros in numeric parts)
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    """Parse a version string into a tuple (major, minor, patch, prerelease, build).
    Raises ValueError if invalid.
    """
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    prerelease = m.group(4)
    build = m.group(5)
    pre_ids = prerelease.split('.') if prerelease is not None else None
    return major, minor, patch, pre_ids, build

def _compare_pre_ids(a: str, b: str) -> int:
    """Compare two pre-release identifiers per SemVer rules."""
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()
    if a_numeric and b_numeric:
        ai = int(a)
        bi = int(b)
        return (ai > bi) - (ai < bi)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    # both non-numeric: ASCII lexical order
    return (a > b) - (a < b)

def _compare_versions(v1: str, v2: str) -> int:
    """Compare two version strings by SemVer precedence. Build metadata ignored."""
    a_major, a_minor, a_patch, a_pre, _ = _parse(v1)
    b_major, b_minor, b_patch, b_pre, _ = _parse(v2)

    if a_major != b_major:
        return (a_major > b_major) - (a_major < b_major)
    if a_minor != b_minor:
        return (a_minor > b_minor) - (a_minor < b_minor)
    if a_patch != b_patch:
        return (a_patch > b_patch) - (a_patch < b_patch)

    # Pre-release precedence
    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1   # no pre-release > with pre-release
    if b_pre is None:
        return -1

    # Compare identifier by identifier
    for x, y in zip(a_pre, b_pre):
        c = _compare_pre_ids(x, y)
        if c != 0:
            return c
    # All compared identifiers equal; longer list has higher precedence
    if len(a_pre) != len(b_pre):
        return (len(a_pre) > len(b_pre)) - (len(a_pre) < len(b_pre))
    return 0

