def glob_match(pattern: str, path: str) -> bool:
    # Tokenize pattern into path segments, respecting backslash escapes.
    # A segment is a list of tokens; '**' is recognized only as a whole segment.
    segments = []
    cur = []
    i = 0
    n = len(pattern)

    def parse_class(seg, i):
        # seg is the pattern string, i points at '['
        j = i + 1
        negated = False
        if j < len(seg) and seg[j] == '!':
            negated = True
            j += 1
        chars = set()
        ranges = []
        first = True
        if j < len(seg) and seg[j] == ']':
            chars.add(']')
            j += 1
            first = False
        while j < len(seg) and seg[j] != ']':
            if first and seg[j] == '-':
                chars.add('-')
                j += 1
                first = False
            elif j + 2 < len(seg) and seg[j + 1] == '-' and seg[j + 2] != ']':
                ranges.append((seg[j], seg[j + 2]))
                j += 3
                first = False
            else:
                chars.add(seg[j])
                j += 1
                first = False
        if j >= len(seg):
            # No closing ']': literal '['
            return None, i + 1
        return ('class', negated, chars, ranges), j + 1

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            cur.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '/':
            segments.append(cur)
            cur = []
            i += 1
        elif c == '?':
            cur.append(('any',))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                # Check if this '**' is a whole segment.
                left_ok = (i == 0) or (pattern[i - 1] == '/')
                # find end of run of '*'
                k = i
                while k < n and pattern[k] == '*':
                    k += 1
                right_ok = (k == n) or (pattern[k] == '/')
                if left_ok and right_ok:
                    cur.append(('globstar',))
                    i = k
                else:
                    cur.append(('star',))
                    i += 1
            else:
                cur.append(('star',))
                i += 1
        elif c == '[':
            tok, ni = parse_class(pattern, i)
            if tok is None:
                cur.append(('lit', '['))
                i = ni
            else:
                cur.append(tok)
                i = ni
        else:
            cur.append(('lit', c))
            i += 1
    segments.append(cur)

    path_segs = path.split('/')

    def match_segment(tokens, s):
        # DP over tokens and string positions
        L = len(s)
        reachable = [False] * (L + 1)
        reachable[0] = True
        for t in tokens:
            new_reach = [False] * (L + 1)
            if t[0] == 'lit':
                ch = t[1]
                for p in range(L):
                    if reachable[p] and s[p] == ch:
                        new_reach[p + 1] = True
            elif t[0] == 'any':
                for p in range(L):
                    if reachable[p] and s[p] != '/':
                        new_reach[p + 1] = True
            elif t[0] == 'star':
                acc = False
                for p in range(L + 1):
                    if reachable[p]:
                        acc = True
                    if acc:
                        new_reach[p] = True
            elif t[0] == 'class':
                _, negated, chars, ranges = t
                for p in range(L):
                    if not reachable[p]:
                        continue
                    ch = s[p]
                    if ch == '/':
                        continue
                    inside = ch in chars
                    if not inside:
                        for lo, hi in ranges:
                            if lo <= ch <= hi:
                                inside = True
                                break
                    if inside != negated:
                        new_reach[p + 1] = True
            reachable = new_reach
        return reachable[L]

    P = len(segments)
    S = len(path_segs)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def rec(pi, si):
        if pi == P:
            return si == S
        seg = segments[pi]
        if len(seg) == 1 and seg[0][0] == 'globstar':
            for k in range(si, S + 1):
                if rec(pi + 1, k):
                    return True
            return False
        if si >= S:
            return False
        if not match_segment(seg, path_segs[si]):
            return False
        return rec(pi + 1, si + 1)

    return rec(0, 0)

