        segments = []
        current = []
        i = 0
        while i < len(p):
            if p[i] == '\\':
                if i + 1 < len(p):
                    current.append(p[i])
                    current.append(p[i + 1])
                    i += 2
                else:
                    raise ValueError("Pattern ends with unpaired backslash")
            elif p[i] == '/':
                segments.append(''.join(current))
                current = []
                i += 1
            else:
                current.append(p[i])
                i += 1
        segments.append(''.join(current))
        return segments

