class Parser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def error(self):
        raise ValueError("syntax error")

    def skip_ws(self):
        while self.i < self.n and self.s[self.i] == ' ':
            self.i += 1

    def peek(self):
        self.skip_ws()
        if self.i < self.n:
            return self.s[self.i]
        return None

    def parse(self):
        self.skip_ws()
        if self.i >= self.n:
            self.error()
        val = self.parse_expr()
        self.skip_ws()
        if self.i != self.n:
            self.error()
        return val

    def parse_expr(self):
        val = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.i += 1
                rhs = self.parse_term()
                val = val + rhs
            elif c == '-':
                self.i += 1
                rhs = self.parse_term()
                val = val - rhs
            else:
                break
        return val

    def parse_term(self):
        val = self.parse_unary()
        while True:
