        self.skip_spaces()
        if self.i >= self.n:
            raise ValueError("Empty expression")
        val = self.parse_expr()
        self.skip_spaces()
        if self.i < self.n:
            raise ValueError(f"Unexpected character: {self.s[self.i]}")
        return val

    def parse_expr(self):
        left = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.consume('+')
                right = self.parse_term()
                left = left + right
            elif c == '-':
                self.consume('-')
                right = self.parse_term()
                left = left - right
            else:
                break
        return left

    def parse_term(self):
        left = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*':
                self.consume('*')
                right = self.parse_unary()
                left = left * right
            elif c == '/':
                self.consume('/')
                right = self.parse_unary()
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right
            else:
                break
        return left

