def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    # Each entry: key -> [value, expiry_time_or_None, last_used_time]
    cache = {}
    results = []

    def purge_expired(now: int) -> None:
        """Remove all entries that are expired at time `now`."""
        expired_keys = [
            k for k, (_, exp, _) in cache.items()
            if exp is not None and now >= exp
        ]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            purge_expired(time)

            expiry = None if ttl is None else time + ttl

            if key in cache:
                # Present and not expired (purge removed expired ones).
                # Replace value/expiry, update recency. No eviction.
                cache[key] = [value, expiry, time]
            else:
                # New key (or previously expired key).
                if len(cache) >= capacity:
                    # Evict least recently used.
                    lru_key = min(cache, key=lambda k: cache[k][2])
                    del cache[lru_key]
                cache[key] = [value, expiry, time]

        elif op[0] == "get":
            _, key, time = op
            purge_expired(time)

            if key in cache:
                value, expiry, _ = cache[key]
                cache[key][2] = time  # update recency
                results.append(value)
            else:
                results.append(None)

    return results

